(function () {
'use strict';
var doc = document;
var burger = doc.querySelector('.ad-burger');
var nav = doc.getElementById('ad-nav');
if (burger && nav) {
burger.addEventListener('click', function () {
var abierto = burger.getAttribute('aria-expanded') === 'true';
burger.setAttribute('aria-expanded', abierto ? 'false' : 'true');
nav.classList.toggle('abierto', !abierto);
});
}
var campos = doc.querySelectorAll('[data-contador]');
for (var i = 0; i < campos.length; i++) {
(function (campo) {
var limite = parseInt(campo.getAttribute('data-contador'), 10);
var etiqueta = doc.querySelector('label[for="' + campo.id + '"]');
if (!etiqueta) { return; }
var marca = doc.createElement('span');
marca.className = 'ad-contador';
etiqueta.appendChild(marca);
var actualizar = function () {
var largo = campo.value.length;
marca.textContent = largo + ' / ' + limite;
marca.classList.toggle('pasado', largo > limite);
};
campo.addEventListener('input', actualizar);
actualizar();
})(campos[i]);
}
var colores = doc.querySelectorAll('[data-color-para]');
for (var c = 0; c < colores.length; c++) {
(function (selector) {
var destino = doc.getElementById(selector.getAttribute('data-color-para'));
if (!destino) { return; }
selector.addEventListener('input', function () { destino.value = selector.value; });
destino.addEventListener('input', function () {
if (/^#[0-9A-Fa-f]{6}$/.test(destino.value)) { selector.value = destino.value; }
});
})(colores[c]);
}
var rutas = doc.querySelectorAll('[data-copiar]');
for (var r = 0; r < rutas.length; r++) {
rutas[r].addEventListener('click', function () {
var texto = this.getAttribute('data-copiar');
var original = this.textContent;
var self = this;
var listo = function () {
self.textContent = 'Copiado';
setTimeout(function () { self.textContent = original; }, 1200);
};
if (navigator.clipboard) {
navigator.clipboard.writeText(texto).then(listo, function () {});
} else {
var tmp = doc.createElement('textarea');
tmp.value = texto;
doc.body.appendChild(tmp);
tmp.select();
try { doc.execCommand('copy'); listo(); } catch (e) {}
doc.body.removeChild(tmp);
}
});
}
var previas = doc.querySelectorAll('[data-vista-previa]');
for (var p = 0; p < previas.length; p++) {
(function (campo) {
campo.addEventListener('change', function () {
var caja = campo.parentNode;
var img = caja.querySelector('img');
if (!campo.value) { if (img) { caja.removeChild(img); } return; }
if (!img) { img = doc.createElement('img'); img.alt = ''; caja.appendChild(img); }
img.src = campo.value;
});
})(previas[p]);
}
var forms = doc.querySelectorAll('form.ad-formulario');
for (var f = 0; f < forms.length; f++) {
(function (form) {
var sucio = false;
form.addEventListener('input', function () { sucio = true; });
form.addEventListener('submit', function () { sucio = false; });
window.addEventListener('beforeunload', function (e) {
if (!sucio) { return; }
e.preventDefault();
e.returnValue = '';
});
})(forms[f]);
}
})();